"use client"

import * as React from "react"
import { GlimmProvider, useGlimm } from "glimm/react"

function Skeleton({ width, height = 8, radius = 6 }: { width: string | number; height?: number; radius?: number }) {
  return <span aria-hidden="true" style={{ background: "#f1f1f2", borderRadius: radius, display: "block", height, width }} />
}

function CloseIcon() {
  return <svg aria-hidden="true" fill="currentColor" height="14" viewBox="0 0 24 24" width="14"><path d="M17.2197 5.71967C17.5126 5.42678 17.9873 5.42678 18.2802 5.71967C18.5731 6.01256 18.5731 6.48732 18.2802 6.78022L13.0605 11.9999L18.2802 17.2197C18.5731 17.5126 18.5731 17.9873 18.2802 18.2802C17.9873 18.5731 17.5126 18.5731 17.2197 18.2802L11.9999 13.0605L6.78022 18.2802C6.48732 18.5731 6.01256 18.5731 5.71967 18.2802C5.42678 17.9873 5.42678 17.5126 5.71967 17.2197L10.9394 11.9999L5.71967 6.78022C5.42678 6.48732 5.42678 6.01256 5.71967 5.71967C6.01256 5.42678 6.48732 5.42678 6.78022 5.71967L11.9999 10.9394L17.2197 5.71967Z" /></svg>
}

function InvoiceIcon() {
  return (
    <div aria-hidden="true" style={{ height: 40, maskImage: "linear-gradient(to bottom, #000 40%, transparent 96%)", overflow: "hidden", position: "relative", width: 46 }}>
      <div style={{ background: "linear-gradient(180deg,#fff,#f1f1f3)", borderRadius: 5, clipPath: "polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%)", height: 68, left: 0, padding: "7px 5px", position: "absolute", top: 0, width: 46 }}>
        <span style={{ background: "rgba(13,13,15,.34)", borderRadius: 2, display: "block", height: 4, width: 21 }} />
        <span style={{ background: "rgba(13,13,15,.14)", borderRadius: 2, display: "block", height: 3, marginTop: 4, width: 28 }} />
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 8 }}><span><Skeleton height={3} width={18} /><span style={{ display: "block", marginTop: 3 }}><Skeleton height={3} width={13} /></span></span><Skeleton height={5} width={10} /></div>
      </div>
    </div>
  )
}

function DashboardShell() {
  return (
    <>
      <aside style={{ background: "#fff", borderRight: "1px solid #ececee", bottom: 0, left: 0, padding: "18px 14px", position: "absolute", top: 0, width: "18.5%" }}>
        <div style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={24} radius={7} width={24} /><Skeleton width={86} /></div>
        <div style={{ display: "grid", gap: 18, marginTop: 30 }}>
          {[48, 82, 118, 72, 96, 62, 106, 88, 66].map((width, index) => <div key={index} style={{ alignItems: "center", display: "flex", gap: 10 }}><Skeleton height={11} width={11} /><Skeleton width={width} /></div>)}
        </div>
        <div style={{ alignItems: "center", bottom: 18, display: "flex", gap: 10, left: 18, position: "absolute" }}><Skeleton height={28} radius={999} width={28} /><Skeleton width={96} /></div>
      </aside>
      <section style={{ bottom: 0, left: "18.5%", position: "absolute", right: 0, top: 0 }}>
        <header style={{ alignItems: "center", borderBottom: "1px solid #ececee", display: "flex", height: 56, justifyContent: "space-between", padding: "0 24px" }}><Skeleton height={16} width={260} /><div style={{ display: "flex", gap: 12 }}><Skeleton height={30} width={30} /><Skeleton height={30} width={30} /><Skeleton height={30} radius={999} width={30} /></div></header>
        <div style={{ padding: "36px 34px" }}>
          <div style={{ alignItems: "center", display: "flex", justifyContent: "space-between" }}><div><Skeleton height={13} width={178} /><div style={{ marginTop: 14 }}><Skeleton width={240} /></div></div><Skeleton height={38} radius={8} width={110} /></div>
          <div style={{ display: "grid", gap: 14, gridTemplateColumns: "repeat(3,1fr)", marginTop: 30 }}>
            {Array.from({ length: 3 }, (_, index) => <article key={index} style={{ border: "1px solid #f0f0f2", borderRadius: 14, padding: 18 }}><Skeleton width={index === 1 ? 72 : 96} /><div style={{ marginTop: 16 }}><Skeleton height={19} width={128} /></div><div style={{ marginTop: 12 }}><Skeleton width="100%" /></div></article>)}
          </div>
          <article style={{ border: "1px solid #f0f0f2", borderRadius: 14, marginTop: 16, overflow: "hidden" }}>
            {Array.from({ length: 7 }, (_, index) => <div key={index} style={{ alignItems: "center", borderBottom: index === 6 ? 0 : "1px solid #ececee", display: "flex", height: 56, justifyContent: "space-between", padding: "0 18px" }}><div style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={30} radius={999} width={30} /><Skeleton width={100 + (index % 3) * 28} /></div><div style={{ alignItems: "center", display: "flex", gap: 14 }}><Skeleton height={20} width={64} /><Skeleton width={54} /></div></div>)}
          </article>
        </div>
      </section>
    </>
  )
}

function InvoicePanel() {
  const [shown, setShown] = React.useState(false)
  const { sweep } = useGlimm()

  const replay = React.useCallback(() => {
    setShown(false)
    window.setTimeout(() => {
      sweep(() => setShown(true), { palette: "azure", direction: "ttb", sweepMs: 1050, outroMs: 180 })
    }, 120)
  }, [sweep])

  React.useEffect(() => {
    const timer = window.setTimeout(replay, 500)
    return () => window.clearTimeout(timer)
  }, [replay])

  return (
    <main style={{ background: "#fff", color: "#242529", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", minHeight: "100vh", overflow: "hidden", position: "relative", width: "100%" }}>
      <DashboardShell />
      <button aria-label="Replay invoice" onClick={replay} type="button" style={{ height: 1, left: 0, opacity: 0, overflow: "hidden", position: "absolute", top: 0, width: 1 }} />
      <section aria-hidden={!shown} role="status" style={{ left: "50%", maxWidth: 392, opacity: shown ? 1 : 0, pointerEvents: shown ? "auto" : "none", position: "absolute", top: 28, transform: shown ? "translate(-50%,0) scale(1)" : "translate(-50%,-12px) scale(.98)", transition: "opacity 260ms ease, transform 320ms cubic-bezier(.23,1,.32,1)", width: "calc(100% - 32px)", zIndex: 20 }}>
        <div style={{ alignItems: "flex-start", backdropFilter: "blur(20px) saturate(1.4)", background: "rgba(38,38,38,.82)", border: ".5px solid rgba(255,255,255,.1)", borderRadius: 16, boxShadow: "0 10px 15px -3px rgba(0,0,0,.1), 0 4px 6px -4px rgba(0,0,0,.1)", display: "flex", gap: 12, overflow: "hidden", padding: 13 }}>
          <InvoiceIcon />
          <div style={{ display: "flex", flex: 1, flexDirection: "column", gap: 10, minWidth: 0 }}>
            <div style={{ alignItems: "center", display: "flex", gap: 10, justifyContent: "space-between", paddingBlock: 1 }}>
              <span style={{ color: "#fff", fontSize: 15, fontWeight: 450, letterSpacing: "-.0156em", lineHeight: 1.33 }}>Your invoice has been paid</span>
              <button aria-label="Dismiss" onClick={() => setShown(false)} type="button" style={{ alignItems: "center", background: "rgba(255,255,255,.08)", border: 0, borderRadius: 999, color: "rgba(255,255,255,.38)", display: "inline-flex", height: 22, justifyContent: "center", padding: 0, width: 22 }}><CloseIcon /></button>
            </div>
            <div style={{ color: "#bfbfbf", fontSize: 13, fontVariantNumeric: "tabular-nums", fontWeight: 450, letterSpacing: "-.0185em", lineHeight: 1.38 }}>Invoice #0042 · $3,240.00</div>
          </div>
        </div>
      </section>
    </main>
  )
}

function GlimmInvoicePaid() {
  return <GlimmProvider><InvoicePanel /></GlimmProvider>
}

export { GlimmInvoicePaid }
export default GlimmInvoicePaid

